// Config — настройки. Меняйте значения справа от двоеточия.
return [{ json: {
  "timezone": "Europe/Kyiv",
  "locale": "ru-RU",
  "sheets_api_base": "https://sheets.googleapis.com/v4",
  "spreadsheet_id": "REPLACE_WITH_SPREADSHEET_ID",
  "runs_sheet": "ParallelRun",
  "token": "REPLACE_WITH_RANDOM_TOKEN",
  "alert_chat_id": "REPLACE_WITH_CHAT_ID",
  "ignore_fields": [
    "id",
    "created_at",
    "updated_at",
    "timestamp",
    "execution_id",
    "zap_id"
  ],
  "compare": {
    "Пример: заявки с сайта": {
      "fields": [],
      "ignore": [
        "internal_note"
      ]
    }
  },
  "wait_minutes": 30,
  "report_hour": 9,
  "ready_days": 3,
  "ready_min_events": 20
} }];

// Record Run — one side of an event arrives; when both are in, the results are compared.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// ParallelRun sheet: one row per event, filled from both sides — the old platform and n8n.
const RCOLS = ['flow', 'key', 'first_at', 'status', 'old_at', 'old_result', 'new_at', 'new_result', 'diff'];
const colLetter = (index) => String.fromCharCode(65 + index);
const runsRange = () => `${quoteSheet(cfg.runs_sheet)}!A1:${colLetter(RCOLS.length - 1)}`;
const runRow = (row) => `${quoteSheet(cfg.runs_sheet)}!A${row}:${colLetter(RCOLS.length - 1)}${row}`;
function runsTable(values) {
  const all = values || [];
  const header = all.length > 0 && String(all[0][0]).trim().toLowerCase() === 'flow';
  return { header, rows: (header ? all.slice(1) : all).map((r, i) => ({ sheetRow: i + (header ? 2 : 1), run: Object.fromEntries(RCOLS.map((c, k) => [c, r[k] === undefined ? '' : String(r[k])])) })) };
}
const putRun = (sheetRow, run) => ({ method: 'PUT', url: sheetUrl(encodeURIComponent(runRow(sheetRow))) + '?valueInputOption=RAW', body: { values: [RCOLS.map((c) => String(run[c] || ''))] } });
const appendRun = (run, hasHeader) => ({ method: 'POST', url: sheetUrl(encodeURIComponent(runsRange()) + ':append') + '?valueInputOption=RAW&insertDataOption=INSERT_ROWS',
  body: { values: [...(hasHeader ? [] : [RCOLS]), RCOLS.map((c) => String(run[c] || ''))] } });
const pad = (n) => String(n).padStart(2, '0');
const stamp = (ms) => { const p = localParts(ms); return `${p.date} ${pad(p.hour)}:${pad(p.minute)}`; };
const parseStamp = (s) => { const m = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})$/.exec(String(s)); if (!m) return Date.parse(s) || 0; const guess = Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]); const p = localParts(guess); return guess - (Date.UTC(+p.date.slice(0, 4), +p.date.slice(5, 7) - 1, +p.date.slice(8, 10), p.hour, p.minute) - guess); };
const plural = (n, one, few, many) => (n % 10 === 1 && n % 100 !== 11 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? few : many);
const req = $('Shadow Log').first().json;
let body = req.body || {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const token = String(body.token || (req.headers || {})['x-shadow-token'] || (req.query || {}).token || '');
if (!cfg.token || String(cfg.token).startsWith('REPLACE') || token !== String(cfg.token)) return [{ json: { ok: false, status: 403, response: { ok: false, error: 'bad token' } } }];
const flow = String(body.flow || '').trim().slice(0, 80);
const key = String(body.key || '').trim().slice(0, 120);
const system = String(body.system || '').toLowerCase();
if (!flow || !key || !['old', 'new'].includes(system)) return [{ json: { ok: false, status: 422, response: { ok: false, error: 'flow, key and system (old|new) are required' } } }];
let result = body.result === undefined ? {} : body.result;
if (typeof result === 'string') { try { result = JSON.parse(result); } catch (e) { result = { value: result }; } }

const rules = Object.assign({ fields: [], ignore: [] }, (cfg.compare || {})[flow] || {});
const ignore = new Set([...(cfg.ignore_fields || []), ...rules.ignore]);
// Values are compared after light normalisation: trimmed text, numbers as numbers, case-insensitive emails.
const normal = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (typeof v === 'object') return JSON.stringify(v, Object.keys(v).sort());
  const s = String(v).trim().replace(/\s+/g, ' ');
  if (/^-?\d+([.,]\d+)?$/.test(s)) return String(Number(s.replace(',', '.')));
  if (/^[^\s@]+@[^\s@]+$/.test(s)) return s.toLowerCase();
  return s;
};
const flat = (obj, prefix = '', out = {}) => {
  if (obj && typeof obj === 'object' && !Array.isArray(obj)) { for (const [k, v] of Object.entries(obj)) flat(v, prefix ? `${prefix}.${k}` : k, out); }
  else out[prefix || 'value'] = obj;
  return out;
};
function compare(a, b) {
  const fa = flat(a), fb = flat(b);
  const keys = rules.fields.length ? rules.fields : [...new Set([...Object.keys(fa), ...Object.keys(fb)])].sort();
  return keys.filter((k) => !ignore.has(k) && !ignore.has(k.split('.').pop())).filter((k) => normal(fa[k]) !== normal(fb[k]))
    .map((k) => `${k}: ${String(normal(fa[k]) || '—').slice(0, 80)} → ${String(normal(fb[k]) || '—').slice(0, 80)}`);
}
const table = runsTable($input.first().json.values);
const now = nowMs();
const found = table.rows.find(({ run }) => run.flow === flow && run.key === key);
const run = found ? Object.assign({}, found.run) : { flow, key, first_at: stamp(now), status: 'waiting' };
run[`${system}_at`] = stamp(now);
run[`${system}_result`] = JSON.stringify(result).slice(0, 4000);
let alert = '';
if (run.old_result && run.new_result) {
  const diff = compare(JSON.parse(run.old_result || '{}'), JSON.parse(run.new_result || '{}'));
  const was = run.status;
  run.status = diff.length ? 'mismatch' : 'match';
  run.diff = diff.join('; ').slice(0, 1000);
  if (diff.length && was !== 'mismatch') alert = [`Расхождение: ${flow}`, `Событие: ${key}`, ...diff.slice(0, 10).map((d) => `• ${d}`), diff.length > 10 ? `…и ещё ${diff.length - 10}` : ''].filter(Boolean).join('\n');
}
return [{ json: { ok: true, status: 200, response: { ok: true, status: run.status }, http: found ? putRun(found.sheetRow, run) : appendRun(run, table.header), alert: Boolean(alert), chat: cfg.alert_chat_id, text: alert } }];
